export async function log(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const parsed = createActivitySchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'activityFeed.error.validationFailed' })
    return
  }

  try {
    // The actor is always the authenticated caller — never trust a client-supplied
    // actorId (createActivitySchema strips it). This prevents feed-entry forgery /
    // impersonation. Mirrors the comment/review/thread create pattern.
    const activity = await logActivity(userId, parsed.data)
    res.status(201).json(activity)
  } catch (error) {
    logger.error('Failed to log activity', { userId, error })
    res.status(500).json({
      error: t('activityFeed.error.logFailed', undefined, {
        defaultValue: 'Failed to log activity',
      }),
      errorKey: 'activityFeed.error.logFailed',
    })
  }
}

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Retrieves the paginated activity feed for the authenticated user.
 *
 * @param req - The request with optional query params for filtering and pagination.
 * @param res - The response object.
 */
export async function feed(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 20))
  const offset = parseInt(req.query.offset as string, 10) || 0
  const resourceType = req.query.resourceType as string | undefined
  const action = req.query.action as string | undefined

  try {
    const result = await getFeed(userId, { limit, offset, resourceType, action })
    res.json(result)
  } catch (error) {
    logger.error('Failed to get activity feed', { userId, error })
    res.status(500).json({
      error: t('activityFeed.error.feedFailed', undefined, {
        defaultValue: 'Failed to get activity feed',
      }),
      errorKey: 'activityFeed.error.feedFailed',
    })
  }
}

/**
 * Returns the number of unseen activities for the authenticated user.
 *
 * @param _req - The request object (unused).
 * @param res - The response object.
 */
export async function unseen(_req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
