    res.json({ count: total })
  } catch (error) {
    logger.error('Failed to count comments', { resourceType, resourceId, error })
    res.status(500).json({
      error: t('comment.error.countFailed', undefined, {
        defaultValue: 'Failed to count comments',
      }),
      errorKey: 'comment.error.countFailed',
    })
  }
}

/**
 * Retrieves a single comment by ID.
 *
 * @param req - The request with `commentId` param.
 * @param res - The response object.
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const { commentId } = req.params
  if (!commentId) {
    res.status(400).json({
      error: t('comment.error.missingId', undefined, { defaultValue: 'Comment ID is required' }),
      errorKey: 'comment.error.missingId',
    })
    return
  }

  try {
    const comment = await getCommentById(commentId)
    if (!comment) {
      res.status(404).json({
        error: t('resource.error.notFound', undefined, { defaultValue: 'Not found.' }),
        errorKey: 'resource.error.notFound',
      })
      return
    }
    res.json(comment)
  } catch (error) {
    logger.error('Failed to read comment', { commentId, error })
    res.status(500).json({
      error: t('comment.error.readFailed', undefined, { defaultValue: 'Failed to read comment' }),
      errorKey: 'comment.error.readFailed',
    })
  }
}

/**
 * Updates an existing comment. Only the comment owner can update.
 *
 * @param req - The request with `commentId` param and update body.
 * @param res - The response object.
 */
export async function update(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { commentId } = req.params
  if (!commentId) {
    res.status(400).json({
      error: t('comment.error.missingId', undefined, { defaultValue: 'Comment ID is required' }),
      errorKey: 'comment.error.missingId',
    })
    return
  }

  const parsed = updateCommentSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'comment.error.validationFailed' })
    return
  }

  try {
    const comment = await updateComment(commentId, userId, parsed.data)
    if (!comment) {
      res.status(404).json({
        error: t('resource.error.notFound', undefined, { defaultValue: 'Not found.' }),
        errorKey: 'resource.error.notFound',
      })
      return
    }
    res.json(comment)
  } catch (error) {
    logger.error('Failed to update comment', { commentId, userId, error })
    res.status(500).json({
      error: t('comment.error.updateFailed', undefined, {
        defaultValue: 'Failed to update comment',
      }),
      errorKey: 'comment.error.updateFailed',
    })
  }
}

/**
 * Deletes a comment. Only the comment owner can delete.
 *
 * @param req - The request with `commentId` param.
 * @param res - The response object.
 */
export async function del(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { commentId } = req.params
  if (!commentId) {
    res.status(400).json({
      error: t('comment.error.missingId', undefined, { defaultValue: 'Comment ID is required' }),
      errorKey: 'comment.error.missingId',
    })
    return
  }

  try {
    const deleted = await deleteComment(commentId, userId)
    if (!deleted) {
      res.status(404).json({
        error: t('resource.error.notFound', undefined, { defaultValue: 'Not found.' }),
        errorKey: 'resource.error.notFound',
      })
      return
    }
    res.status(204).end()
  } catch (error) {
    logger.error('Failed to delete comment', { commentId, userId, error })
    res.status(500).json({
      error: t('comment.error.deleteFailed', undefined, {
        defaultValue: 'Failed to delete comment',
      }),
      errorKey: 'comment.error.deleteFailed',
    })
  }
}

/**
 * Lists paginated replies to a comment.
 *
 * @param req - The request with `commentId` param.
 * @param res - The response object.
 */
export async function replies(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const { commentId } = req.params
  if (!commentId) {
    res.status(400).json({
      error: t('comment.error.missingId', undefined, { defaultValue: 'Comment ID is required' }),
      errorKey: 'comment.error.missingId',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 20))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const result = await getReplies(commentId, { limit, offset })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list replies', { commentId, error })
    res.status(500).json({
      error: t('comment.error.repliesFailed', undefined, {
        defaultValue: 'Failed to list replies',
      }),
      errorKey: 'comment.error.repliesFailed',
    })
  }
}

