import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { logger } from '@molecule/api-logger'
import type { MoleculeRequest, MoleculeResponse } from '@molecule/api-resource'
import {
  follow,
  getFollowers,
  getFollowing,
  isFollowing,
  unfollow,
} from '@molecule/api-resource-follow'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-follow own storage.

/**
 * Creates a follow relationship. Idempotent.
 *
 * @param req - The request with `targetType` and `targetId` params.
 * @param res - The response object.
 */
export async function create(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { targetType, targetId } = req.params
  if (!targetType || !targetId) {
    res.status(400).json({
      error: t('follow.error.missingTarget', undefined, {
        defaultValue: 'Target type and ID are required',
      }),
      errorKey: 'follow.error.missingTarget',
    })
    return
  }

  try {
    const result = await follow(userId, targetType, targetId)
    res.status(201).json(result)
  } catch (error) {
    logger.error('Failed to follow', { userId, targetType, targetId, error })
    res.status(500).json({
      error: t('follow.error.createFailed', undefined, { defaultValue: 'Failed to follow' }),
      errorKey: 'follow.error.createFailed',
    })
  }
}

/**
 * Removes a follow relationship.
 *
 * @param req - The request with `targetType` and `targetId` params.
 * @param res - The response object.
 */
export async function del(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { targetType, targetId } = req.params
  if (!targetType || !targetId) {
    res.status(400).json({
      error: t('follow.error.missingTarget', undefined, {
        defaultValue: 'Target type and ID are required',
      }),
      errorKey: 'follow.error.missingTarget',
    })
    return
  }

  try {
    await unfollow(userId, targetType, targetId)
    res.status(204).end()
  } catch (error) {
    logger.error('Failed to unfollow', { userId, targetType, targetId, error })
    res.status(500).json({
      error: t('follow.error.deleteFailed', undefined, { defaultValue: 'Failed to unfollow' }),
      errorKey: 'follow.error.deleteFailed',
    })
  }
}

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Lists paginated followers of a target.
 *
 * @param req - The request with `targetType` and `targetId` params.
 * @param res - The response object.
 */
export async function list(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const { targetType, targetId } = req.params
  if (!targetType || !targetId) {
    res.status(400).json({
      error: t('follow.error.missingTarget', undefined, {
        defaultValue: 'Target type and ID are required',
      }),
      errorKey: 'follow.error.missingTarget',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 20))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const result = await getFollowers(targetType, targetId, { limit, offset })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list followers', { targetType, targetId, error })
    res.status(500).json({
      error: t('follow.error.listFailed', undefined, {
        defaultValue: 'Failed to list followers',
      }),
      errorKey: 'follow.error.listFailed',
    })
  }
}

/**
 * Lists targets the current user is following.
 *
 * @param req - The request with pagination query params.
 * @param res - The response object.
 */
export async function following(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 20))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const result = await getFollowing(userId, { limit, offset })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list following', { userId, error })
    res.status(500).json({
      error: t('follow.error.followingFailed', undefined, {
        defaultValue: 'Failed to list following',
      }),
      errorKey: 'follow.error.followingFailed',
    })
  }
}

/**
 * Checks if the current user is following a target.
 *
 * @param req - The request with `targetType` and `targetId` params.
 * @param res - The response object.
 */
export async function checkFollowing(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { targetType, targetId } = req.params
  if (!targetType || !targetId) {
    res.status(400).json({
      error: t('follow.error.missingTarget', undefined, {
        defaultValue: 'Target type and ID are required',
      }),
      errorKey: 'follow.error.missingTarget',
    })
    return
  }

  try {
    const result = await isFollowing(userId, targetType, targetId)
    res.json({ following: result })
  } catch (error) {
    logger.error('Failed to check follow status', { userId, targetType, targetId, error })
    res.status(500).json({
      error: t('follow.error.checkFailed', undefined, {
        defaultValue: 'Failed to check follow status',
      }),
      errorKey: 'follow.error.checkFailed',
    })
  }
}

const router = Router()

router.post('/follow/:targetType/:targetId', create)
router.delete('/follow/:targetType/:targetId', del)
router.get('/:targetType/:targetId/followers', list)
router.get('/following', following)
router.get('/follow/check/:targetType/:targetId', checkFollowing)

export default router

