import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { logger } from '@molecule/api-logger'
import type { MoleculeRequest, MoleculeResponse } from '@molecule/api-resource'
import {
  deleteMessage,
  editMessage,
  editMessageSchema,
  getOrCreateThread,
  getOrCreateThreadSchema,
  getThreadById,
  getTotalUnreadCount,
  listMessages,
  listThreadsForParticipant,
  markRead,
  sendMessage,
  sendMessageSchema,
} from '@molecule/api-resource-message'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-message own storage.

/**
 * Resolves (or lazily creates) the canonical thread between the
 * authenticated user and a counter-participant.
 *
 * @param req - The request with `participantId` in body.
 * @param res - The response object.
 */
export async function createThread(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const parsed = getOrCreateThreadSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'message.error.validationFailed' })
    return
  }

  if (parsed.data.participantId === userId) {
    res.status(400).json({
      error: t('message.error.selfThread', undefined, {
        defaultValue: 'Cannot start a thread with yourself',
      }),
      errorKey: 'message.error.selfThread',
    })
    return
  }

  try {
    const thread = await getOrCreateThread(userId, parsed.data.participantId)
    res.status(201).json(thread)
  } catch (error) {
    logger.error('Failed to create message thread', { userId, error })
    res.status(500).json({
      error: t('message.error.threadCreateFailed', undefined, {
        defaultValue: 'Failed to create thread',
      }),
      errorKey: 'message.error.threadCreateFailed',
    })
  }
}

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Returns paginated threads for the authenticated user, newest first.
 *
 * @param req - The request with optional `limit` / `offset` query params.
 * @param res - The response object.
 */
export async function listThreads(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 50))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const threads = await listThreadsForParticipant(userId, { limit, offset })
    res.json({ data: threads, limit, offset })
  } catch (error) {
    logger.error('Failed to list threads', { userId, error })
    res.status(500).json({
      error: t('message.error.listThreadsFailed', undefined, {
        defaultValue: 'Failed to list threads',
      }),
      errorKey: 'message.error.listThreadsFailed',
    })
  }
}

/**
 * Returns the thread identified by `:threadId`. The authenticated user
 * must be a participant.
 *
 * @param req - The request with `threadId` URL param.
 * @param res - The response object.
 */
export async function readThread(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { threadId } = req.params
  if (!threadId) {
    res.status(400).json({
      error: t('message.error.missingThreadId', undefined, {
        defaultValue: 'Thread ID is required',
      }),
      errorKey: 'message.error.missingThreadId',
    })
    return
  }

  try {
    const thread = await getThreadById(threadId)
    if (!thread) {
      res.status(404).json({
        error: t('message.error.threadNotFound', undefined, {
          defaultValue: 'Thread not found',
        }),
        errorKey: 'message.error.threadNotFound',
      })
      return
    }
    if (thread.participantAId !== userId && thread.participantBId !== userId) {
      res.status(403).json({
        error: t('message.error.notParticipant', undefined, {
          defaultValue: 'You are not a participant in this thread',
        }),
        errorKey: 'message.error.notParticipant',
      })
      return
    }
    res.json(thread)
  } catch (error) {
    logger.error('Failed to read thread', { threadId, error })
    res.status(500).json({
      error: t('message.error.readThreadFailed', undefined, {
        defaultValue: 'Failed to read thread',
      }),
      errorKey: 'message.error.readThreadFailed',
    })
  }
}

/**
 * Lists messages in a thread, newest first.
 *
 * @param req - The request with `threadId` URL param and optional
 *   `before` / `limit` query params.
 * @param res - The response object.
 */
export async function listMessagesHandler(
  req: MoleculeRequest,
  res: MoleculeResponse,
): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { threadId } = req.params
  if (!threadId) {
    res.status(400).json({
      error: t('message.error.missingThreadId', undefined, {
        defaultValue: 'Thread ID is required',
      }),
      errorKey: 'message.error.missingThreadId',
    })
    return
  }

  const thread = await getThreadById(threadId)
  if (!thread) {
    res.status(404).json({
      error: t('message.error.threadNotFound', undefined, {
        defaultValue: 'Thread not found',
      }),
      errorKey: 'message.error.threadNotFound',
    })
    return
  }
  if (thread.participantAId !== userId && thread.participantBId !== userId) {
    res.status(403).json({
      error: t('message.error.notParticipant', undefined, {
        defaultValue: 'You are not a participant in this thread',
      }),
      errorKey: 'message.error.notParticipant',
    })
    return
  }

  const before = typeof req.query.before === 'string' ? req.query.before : undefined
  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 50))

  try {
    const messages = await listMessages(threadId, { before, limit })
    res.json({ data: messages, limit })
  } catch (error) {
    logger.error('Failed to list messages', { threadId, error })
    res.status(500).json({
      error: t('message.error.listMessagesFailed', undefined, {
        defaultValue: 'Failed to list messages',
      }),
      errorKey: 'message.error.listMessagesFailed',
    })
  }
}

/**
 * Sends a new message in a thread. Authenticated user must be a
 * participant. Broadcasts a `message:sent` event when realtime is bonded.
 *
 * @param req - The request with `threadId` URL param and message body.
 * @param res - The response object.
 */
export async function sendMessageHandler(
  req: MoleculeRequest,
  res: MoleculeResponse,
): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { threadId } = req.params
  if (!threadId) {
    res.status(400).json({
      error: t('message.error.missingThreadId', undefined, {
        defaultValue: 'Thread ID is required',
      }),
      errorKey: 'message.error.missingThreadId',
    })
    return
  }

  const parsed = sendMessageSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'message.error.validationFailed' })
    return
  }

  try {
    const message = await sendMessage(threadId, userId, parsed.data.body, parsed.data.attachments)
    res.status(201).json(message)
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error'
    if (errorMessage.includes('not found')) {
      res.status(404).json({
        error: t('message.error.threadNotFound', undefined, {
          defaultValue: 'Thread not found',
        }),
        errorKey: 'message.error.threadNotFound',
      })
      return
    }
    if (errorMessage.includes('not a participant')) {
      res.status(403).json({
        error: t('message.error.notParticipant', undefined, {
          defaultValue: 'You are not a participant in this thread',
        }),
        errorKey: 'message.error.notParticipant',
      })
      return
    }
    logger.error('Failed to send message', { threadId, userId, error })
    res.status(500).json({
      error: t('message.error.sendFailed', undefined, {
        defaultValue: 'Failed to send message',
      }),
      errorKey: 'message.error.sendFailed',
    })
  }
}

