import { type Request, type Response, Router } from 'express'

import {
  deleteNotification,
  getAll,
  getPreferences,
  getUnreadCount,
  markAllRead,
  markRead,
  setPreferences,
} from '@molecule/api-notification-center'
import { getSessionUserId } from '@molecule/api-resource-notification'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-notification own storage.

/** The page-size ceiling: `limit` is caller-controlled and must not be unbounded. */
const MAX_LIST_LIMIT = 500

/**
 * Parse + clamp the caller's `limit` query param to 1..MAX (the fleet-wide
 * limit-clamp shape); garbage or a present-but-zero value falls back to the
 * provider's default (`undefined`).
 */
const toLimit = (raw: unknown): number | undefined => {
  const n = Number(raw)
  return raw && Number.isFinite(n)
    ? Math.min(MAX_LIST_LIMIT, Math.max(1, Math.trunc(n)))
    : undefined
}

/** Parse + clamp the caller's `offset` query param to >= 0; garbage falls back to the default. */
const toOffset = (raw: unknown): number | undefined => {
  const n = Number(raw)
  return raw && Number.isFinite(n) ? Math.max(0, Math.trunc(n)) : undefined
}

/**
 * Handles GET /notifications requests.
 *
 * @param req - Express request with optional query params: limit, offset, read, type.
 * @param res - Express response.
 */
export async function list(req: Request, res: Response): Promise<void> {
  const userId = getSessionUserId(res)
  if (!userId) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }
  const { limit, offset, read, type } = req.query

  const result = await getAll(userId, {
    limit: toLimit(limit),
    offset: toOffset(offset),
    read: read !== undefined ? read === 'true' : undefined,
    type: type ? String(type) : undefined,
  })

  res.json(result)
}

/**
 * Handles GET /notifications/unread-count requests.
 *
 * @param req - Express request with authenticated user.
 * @param res - Express response.
 */
export async function unreadCount(_req: Request, res: Response): Promise<void> {
  const userId = getSessionUserId(res)
  if (!userId) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }
  const count = await getUnreadCount(userId)
  res.json({ count })
}

/**
 * Handles POST /notifications/:id/read requests.
 *
 * Requires an authenticated session and only affects the requester's own
 * notification — a notification belonging to another user (or a non-existent
 * id) yields a 404, never silently mutating someone else's row (IDOR).
 *
 * @param req - Express request with notification id param.
 * @param res - Express response.
 */
export async function markReadHandler(req: Request<{ id: string }>, res: Response): Promise<void> {
  const userId = getSessionUserId(res)
  if (!userId) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }

  const updated = await markRead(userId, req.params.id)
  if (!updated) {
    res.status(404).json({ error: 'Not Found' })
    return
  }

  res.status(204).end()
}

/**
 * Handles POST /notifications/read-all requests.
 *
 * @param req - Express request with authenticated user.
 * @param res - Express response.
 */
export async function markAllReadHandler(_req: Request, res: Response): Promise<void> {
  const userId = getSessionUserId(res)
  if (!userId) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }
  await markAllRead(userId)
  res.status(204).end()
}

/**
 * Handles DELETE /notifications/:id requests.
 *
 * Requires an authenticated session and only deletes the requester's own
 * notification — a notification belonging to another user (or a non-existent
 * id) yields a 404, never deleting someone else's row (IDOR).
 *
 * @param req - Express request with notification id param.
 * @param res - Express response.
 */
export async function del(req: Request<{ id: string }>, res: Response): Promise<void> {
  const userId = getSessionUserId(res)
  if (!userId) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }

  const deleted = await deleteNotification(userId, req.params.id)
  if (!deleted) {
    res.status(404).json({ error: 'Not Found' })
    return
  }

  res.status(204).end()
}

/**
 * Handles GET /notifications/preferences requests.
 *
 * @param req - Express request with authenticated user.
 * @param res - Express response.
 */
export async function getPreferencesHandler(_req: Request, res: Response): Promise<void> {
  const userId = getSessionUserId(res)
  if (!userId) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }
  const preferences = await getPreferences(userId)
  res.json(preferences)
}

/**
 * Handles PUT /notifications/preferences requests.
 *
 * @param req - Express request with preferences in body.
 * @param res - Express response.
 */
export async function updatePreferencesHandler(req: Request, res: Response): Promise<void> {
  const userId = getSessionUserId(res)
  if (!userId) {
    res.status(401).json({ error: 'Unauthorized' })
    return
  }
  await setPreferences(userId, req.body as Record<string, unknown>)
  res.status(204).end()
}

const router = Router()

router.get('/notifications', list)
router.get('/notifications/unread-count', unreadCount)
router.get('/notifications/preferences', getPreferencesHandler)
router.post('/notifications/:id/read', markReadHandler)
router.post('/notifications/read-all', markAllReadHandler)
router.put('/notifications/preferences', updatePreferencesHandler)
router.delete('/notifications/:id', del)

export default router

