import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { type MoleculeRequest, type MoleculeResponse, respondError } from '@molecule/api-resource'
import {
  createSetupIntent as createSetupIntentService,
  deletePaymentMethod as deleteService,
  listPaymentMethods as listPaymentMethodsService,
  setDefaultPaymentMethod as setDefaultService,
} from '@molecule/api-resource-payment-method'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-payment-method own storage.

/**
 * Issues a SetupIntent for the authenticated user.
 *
 * @param _req - The request (no body required).
 * @param res - The response object.
 */
export async function createSetupIntent(
  _req: MoleculeRequest,
  res: MoleculeResponse,
): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('paymentMethod.error.unauthorized', undefined, { defaultValue: 'Unauthorized' }),
      errorKey: 'paymentMethod.error.unauthorized',
    })
    return
  }

  try {
    const intent = await createSetupIntentService(userId)
    res.status(201).json(intent)
  } catch (error) {
    // A tagged provider error (e.g. missing STRIPE_SECRET_KEY → 503 + 'config.notConfigured')
    // surfaces its real status/errorKey; anything else falls back to the generic 500.
    respondError(res, error, {
      status: 500,
      message: t('paymentMethod.error.setupIntentFailed', undefined, {
        defaultValue: 'Failed to create setup intent',
      }),
      errorKey: 'paymentMethod.error.setupIntentFailed',
    })
  }
}

/**
 * Returns every saved payment method for the authenticated user.
 *
 * @param _req - The request (no body required).
 * @param res - The response object.
 */
export async function listPaymentMethods(
  _req: MoleculeRequest,
  res: MoleculeResponse,
): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('paymentMethod.error.unauthorized', undefined, { defaultValue: 'Unauthorized' }),
      errorKey: 'paymentMethod.error.unauthorized',
    })
    return
  }

  try {
    const methods = await listPaymentMethodsService(userId)
    res.json(methods)
  } catch (error) {
    respondError(res, error, {
      status: 500,
      message: t('paymentMethod.error.listFailed', undefined, {
        defaultValue: 'Failed to list payment methods',
      }),
      errorKey: 'paymentMethod.error.listFailed',
    })
  }
}

/**
 * Promotes a saved payment method to default. Enforces ownership via the
 * service layer.
 *
 * @param req - The request with `:id` route param.
 * @param res - The response object.
 */
export async function setDefaultPaymentMethod(
  req: MoleculeRequest,
  res: MoleculeResponse,
): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('paymentMethod.error.unauthorized', undefined, { defaultValue: 'Unauthorized' }),
      errorKey: 'paymentMethod.error.unauthorized',
    })
    return
  }

  const id = req.params?.id
  if (!id) {
    res.status(400).json({
      error: t('paymentMethod.error.idRequired', undefined, {
        defaultValue: 'Payment method id is required',
      }),
      errorKey: 'paymentMethod.error.idRequired',
    })
    return
  }

  try {
    const updated = await setDefaultService(userId, id)
    if (!updated) {
      res.status(404).json({
        error: t('paymentMethod.error.notFound', undefined, {
          defaultValue: 'Payment method not found',
        }),
        errorKey: 'paymentMethod.error.notFound',
      })
      return
    }
    res.json(updated)
  } catch (error) {
    respondError(res, error, {
      status: 500,
      message: t('paymentMethod.error.setDefaultFailed', undefined, {
        defaultValue: 'Failed to set default payment method',
      }),
      errorKey: 'paymentMethod.error.setDefaultFailed',
    })
  }
}

