    res.json(stats)
  } catch (error) {
    logger.error('Failed to get average rating', { resourceType, resourceId, error })
    res.status(500).json({
      error: t('review.error.ratingFailed', undefined, {
        defaultValue: 'Failed to get rating statistics',
      }),
      errorKey: 'review.error.ratingFailed',
    })
  }
}

/**
 * Retrieves a single review by ID.
 *
 * @param req - The request with `reviewId` param.
 * @param res - The response object.
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const { reviewId } = req.params
  if (!reviewId) {
    res.status(400).json({
      error: t('review.error.missingId', undefined, { defaultValue: 'Review ID is required' }),
