@molecule/api-resource-share.expressRouter:
import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { logger } from '@molecule/api-logger'
import type { MoleculeRequest, MoleculeResponse } from '@molecule/api-resource'
import {
  canAdministerResource,
  getEffectiveRole,
  listShareLinks,
  listShares,
  type PrincipalType,
  resolveShareLink,
} from '@molecule/api-resource-share'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-share own storage.

const VALID_PRINCIPAL_TYPES: PrincipalType[] = ['user', 'team', 'public']

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Lists shares attached to a resource, identified by `resourceType` and
 * `resourceId` query/path params.
 *
 * @param req - The request with `resourceType`, `resourceId` params and optional pagination/filter query.
 * @param res - The response object.
 */
export async function list(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const resourceType = (req.params.resourceType ?? req.query.resourceType) as string | undefined
  const resourceId = (req.params.resourceId ?? req.query.resourceId) as string | undefined

  if (!resourceType || !resourceId) {
    res.status(400).json({
      error: t('share.error.missingResource', undefined, {
        defaultValue: 'Resource type and ID are required',
      }),
      errorKey: 'share.error.missingResource',
    })
    return
  }

  // Listing the full ACL of a resource (every principal id + role + grantedBy)
  // is a manage-level operation: it discloses the entire sharing graph. Gate it
  // behind the same default-DENY resource-ownership authorizer the mutating
  // grant/update/revoke handlers use, so an authenticated user can only enumerate
  // shares on resources they administer — never on an arbitrary resource id. The
  // privacy-preserving primitive for non-managers remains the `read` handler,
  // which returns only the caller's OWN effective role.
  if (!(await canAdministerResource(resourceType, resourceId, userId))) {
    res.status(403).json({
      error: t('share.error.forbidden', undefined, {
        defaultValue: 'You are not allowed to manage shares on this resource',
      }),
      errorKey: 'share.error.forbidden',
    })
    return
  }

  const principalTypeRaw = req.query.principalType as string | undefined
  const principalType =
    principalTypeRaw && VALID_PRINCIPAL_TYPES.includes(principalTypeRaw as PrincipalType)
      ? (principalTypeRaw as PrincipalType)
      : undefined
  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 50))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const result = await listShares(resourceType, resourceId, { principalType, limit, offset })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list shares', { userId, resourceType, resourceId, error })
    res.status(500).json({
      error: t('share.error.listFailed', undefined, {
        defaultValue: 'Failed to list shares',
      }),
      errorKey: 'share.error.listFailed',
    })
  }
}

/**
 * Returns the effective role the current user has on the resource,
 * considering direct user grants, team grants (if `teamIds` provided in
 * `res.locals.session`), and any active public grant.
 *
 * @param req - The request with `resourceType` and `resourceId` params.
 * @param res - The response object.
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const session = res.locals.session as { userId?: string; teamIds?: string[] } | undefined
  const userId = session?.userId ?? null
  const teamIds = session?.teamIds ?? []

  const { resourceType, resourceId } = req.params
  if (!resourceType || !resourceId) {
    res.status(400).json({
      error: t('share.error.missingResource', undefined, {
        defaultValue: 'Resource type and ID are required',
      }),
      errorKey: 'share.error.missingResource',
    })
    return
  }

  try {
    const role = await getEffectiveRole(resourceType, resourceId, userId, teamIds)
    res.json({ role })
  } catch (error) {
    logger.error('Failed to read effective role', { userId, resourceType, resourceId, error })
    res.status(500).json({
      error: t('share.error.readFailed', undefined, {
        defaultValue: 'Failed to read effective role',
      }),
      errorKey: 'share.error.readFailed',
    })
  }
}

/**
 * Lists all public share links attached to a resource.
 *
 * @param req - The request with `resourceType` and `resourceId` params.
 * @param res - The response object.
 */
export async function listLinks(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { resourceType, resourceId } = req.params
  if (!resourceType || !resourceId) {
    res.status(400).json({
      error: t('share.error.missingResource', undefined, {
        defaultValue: 'Resource type and ID are required',
      }),
      errorKey: 'share.error.missingResource',
    })
    return
  }

  // Listing every share link of a resource discloses its slugs (each slug is a
  // bearer credential granting access) plus the full link graph. Like `list`,
  // this is a manage-level operation: gate it behind the same default-DENY
  // resource-ownership authorizer so an authenticated user can only enumerate
  // links on resources they administer, never on an arbitrary resource id.
  if (!(await canAdministerResource(resourceType, resourceId, userId))) {
    res.status(403).json({
      error: t('share.error.forbidden', undefined, {
        defaultValue: 'You are not allowed to manage shares on this resource',
      }),
      errorKey: 'share.error.forbidden',
    })
    return
  }

  try {
    const links = await listShareLinks(resourceType, resourceId)
    res.json({ data: links })
  } catch (error) {
    logger.error('Failed to list share links', { userId, resourceType, resourceId, error })
    res.status(500).json({
      error: t('share.error.linkListFailed', undefined, {
        defaultValue: 'Failed to list share links',
      }),
      errorKey: 'share.error.linkListFailed',
    })
  }
}

/**
 * Resolves a public share-link slug to its `ShareLink` record. Returns
 * 404 when the slug is unknown, revoked, or expired. Does NOT require
 * authentication — the slug is the credential.
 *
 * @param req - The request with `slug` param.
 * @param res - The response object.
 */
export async function resolveLink(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const { slug } = req.params
  if (!slug) {
    res.status(400).json({
      error: t('share.error.missingSlug', undefined, { defaultValue: 'Slug is required' }),
      errorKey: 'share.error.missingSlug',
    })
    return
  }

  try {
    const link = await resolveShareLink(slug)
    if (!link) {
      res.status(404).json({
        error: t('share.error.linkNotFound', undefined, {
          defaultValue: 'Share link not found',
        }),
        errorKey: 'share.error.linkNotFound',
      })
      return
    }
    res.json(link)
  } catch (error) {
    logger.error('Failed to resolve share link', { slug, error })
    res.status(500).json({
      error: t('share.error.linkResolveFailed', undefined, {
        defaultValue: 'Failed to resolve share link',
      }),
      errorKey: 'share.error.linkResolveFailed',
    })
  }
}

const router = Router()

router.get('/resource-shares/:resourceType/:resourceId', list)
router.get('/resource-shares/:resourceType/:resourceId/role', read)
router.get('/resource-share-links/:resourceType/:resourceId', listLinks)
router.get('/resource-share-links/resolve/:slug', resolveLink)

export default router

