import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { logger } from '@molecule/api-logger'
import type { MoleculeRequest, MoleculeResponse } from '@molecule/api-resource'
import {
  canEditTemplate,
  canViewTemplate,
  createTemplate,
  createTemplateSchema,
  deleteTemplate,
  getTemplate,
  instantiateSchema,
  instantiateTemplate,
  listTemplates,
  updateTemplate,
  updateTemplateSchema,
} from '@molecule/api-resource-template'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-template own storage.

/**
 * Creates a new template entry. Returns `409 Conflict` if a row already
 * exists for the same `(resourceType, slug)` pair.
 *
 * @param req - Request with creation body.
 * @param res - Response object.
 */
export async function create(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const parsed = createTemplateSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'template.error.validationFailed' })
    return
  }

  try {
    const tpl = await createTemplate({ ...parsed.data, createdBy: userId })
    res.status(201).json(tpl)
  } catch (error) {
    if ((error as { code?: string }).code === 'conflict') {
      res.status(409).json({
        error: t('template.error.conflict', undefined, {
          defaultValue: 'Template with that slug already exists',
        }),
        errorKey: 'template.error.conflict',
      })
      return
    }
    logger.error('Failed to create template', { userId, error })
    res.status(500).json({
      error: t('template.error.createFailed', undefined, {
        defaultValue: 'Failed to create template',
      }),
      errorKey: 'template.error.createFailed',
    })
  }
}

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Lists templates with optional filtering by `resourceType`, `tags`, and
 * `publicOnly`.
 *
 * @param req - Request with optional query string filters.
 * @param res - Response object.
 */
export async function list(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const resourceType = req.query.resourceType as string | undefined
  const publicOnly = req.query.publicOnly === 'true' || req.query.publicOnly === '1'
  const createdBy = req.query.createdBy as string | undefined
  const tagsRaw = req.query.tags as string | string[] | undefined
  const tags = Array.isArray(tagsRaw)
    ? tagsRaw
    : typeof tagsRaw === 'string' && tagsRaw.length > 0
      ? tagsRaw
          .split(',')
          .map((s) => s.trim())
          .filter(Boolean)
      : undefined
  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 50))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const result = await listTemplates({
      // Scope visibility to the authenticated caller (derived from the session,
      // enforced in-handler — not via a route middleware the scaffolder may strip):
      // a non-owner never sees another user's private templates.
      viewerId: userId,
      resourceType,
      publicOnly,
      createdBy,
      tags,
      limit,
      offset,
    })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list templates', { userId, error })
    res.status(500).json({
      error: t('template.error.listFailed', undefined, {
        defaultValue: 'Failed to list templates',
      }),
      errorKey: 'template.error.listFailed',
    })
  }
}

/**
 * Reads a single template by ID.
 *
 * @param req - Request with `id` path param.
 * @param res - Response object.
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id } = req.params
  if (!id) {
    res.status(400).json({
      error: t('template.error.missingId', undefined, { defaultValue: 'Template ID is required' }),
      errorKey: 'template.error.missingId',
    })
    return
  }

  try {
    const tpl = await getTemplate(id)
    // Ownership/visibility is enforced HERE (not via route middleware the scaffolder
