/**
 * Creates a new discussion thread.
 *
 * @param req - The request with thread creation body.
 * @param res - The response object.
 */
export async function create(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const parsed = createThreadSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'thread.error.validationFailed' })
    return
  }

  try {
    const thread = await createThread(userId, parsed.data)
    res.status(201).json(thread)
  } catch (error) {
    logger.error('Failed to create thread', { userId, error })
    res.status(500).json({
      error: t('thread.error.createFailed', undefined, {
        defaultValue: 'Failed to create thread',
      }),
      errorKey: 'thread.error.createFailed',
    })
  }
}

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Lists paginated threads for the authenticated user.
 *
 * @param req - The request with optional query params for filtering and pagination.
 * @param res - The response object.
 */
export async function list(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 20))
  const offset = parseInt(req.query.offset as string, 10) || 0
  const resourceType = req.query.resourceType as string | undefined
  const resourceId = req.query.resourceId as string | undefined
  const closedParam = req.query.closed as string | undefined
  const closed = closedParam === 'true' ? true : closedParam === 'false' ? false : undefined

  try {
    const result = await getThreads(userId, { limit, offset, resourceType, resourceId, closed })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list threads', { userId, error })
    res.status(500).json({
      error: t('thread.error.listFailed', undefined, { defaultValue: 'Failed to list threads' }),
      errorKey: 'thread.error.listFailed',
    })
  }
}

/**
 * Retrieves a single thread by ID.
 *
 * @param req - The request with `threadId` param.
 * @param res - The response object.
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  // [M6-1] Threads are private (creator-owned). The route's bare `authenticate` is stripped
  // by the scaffold scanner, so this handler must fail closed itself — otherwise an anonymous
  // caller could read any thread by id (IDOR on private conversations). Mirrors the sibling
  // handlers (list/unread/…) and the @molecule/api-resource-message participant gate.
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }
  const { threadId } = req.params
  if (!threadId) {
    res.status(400).json({
      error: t('thread.error.missingId', undefined, { defaultValue: 'Thread ID is required' }),
      errorKey: 'thread.error.missingId',
    })
    return
  }

  try {
    const thread = await getThreadById(threadId)
    // 404 (not 403) for a non-owner so a thread's existence is not leaked.
    if (!thread || thread.creatorId !== userId) {
      res.status(404).json({
        error: t('resource.error.notFound', undefined, { defaultValue: 'Not found.' }),
        errorKey: 'resource.error.notFound',
      })
      return
    }
    res.json(thread)
  } catch (error) {
    logger.error('Failed to read thread', { threadId, error })
    res.status(500).json({
      error: t('thread.error.readFailed', undefined, { defaultValue: 'Failed to read thread' }),
      errorKey: 'thread.error.readFailed',
    })
  }
}

