@molecule/api-resource-version-history.expressRouter:
import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { logger } from '@molecule/api-logger'
import type { MoleculeRequest, MoleculeResponse } from '@molecule/api-resource'
import {
  createVersion,
  createVersionSchema,
  diffVersions,
  getVersionById,
  getVersionByNumber,
  getVersionCount,
  getVersionsForResource,
  isVersionAuthorized,
  restoreVersion,
  restoreVersionSchema,
} from '@molecule/api-resource-version-history'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-version-history own storage.

/**
 * Captures a new version of a resource.
 *
 * Secure by default: returns 401 with no session, and 404 (no existence leak)
 * when the caller is not authorized for the parent resource — a caller can only
 * capture versions of a resource they own, never inject snapshots into another
 * tenant's resource.
 *
 * @param req - The request with `resourceType` / `resourceId` params and a snapshot body.
 * @param res - The response object (reads `locals.session`/`locals.versionHistoryAdmin`).
 */
export async function create(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { resourceType, resourceId } = req.params
  if (!resourceType || !resourceId) {
    res.status(400).json({
      error: t('versionHistory.error.missingResource', undefined, {
        defaultValue: 'Resource type and ID are required',
      }),
      errorKey: 'versionHistory.error.missingResource',
    })
    return
  }

  if (!(await isVersionAuthorized(res, { resourceType, resourceId, userId }))) {
    res.status(404).json({
      error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
      errorKey: 'versionHistory.error.notFound',
    })
    return
  }

  const parsed = createVersionSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'versionHistory.error.validationFailed' })
    return
  }

  try {
    const version = await createVersion({
      resourceType,
      resourceId,
      userId,
      snapshot: parsed.data.snapshot as Parameters<typeof createVersion>[0]['snapshot'],
      reason: parsed.data.reason ?? null,
    })
    res.status(201).json(version)
  } catch (error) {
    logger.error('Failed to create version', { resourceType, resourceId, userId, error })
    res.status(500).json({
      error: t('versionHistory.error.createFailed', undefined, {
        defaultValue: 'Failed to create version',
      }),
      errorKey: 'versionHistory.error.createFailed',
    })
  }
}

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Lists paginated versions for a resource, newest version first.
 *
 * Secure by default: returns 401 with no session, and 404 (no existence leak)
 * when the caller is not authorized for the parent resource — only the parent
 * resource's owner (or an opt-in {@link versionHistoryAdmin}) sees its versions.
 *
 * @param req - The request with `resourceType` and `resourceId` params.
 * @param res - The response object (reads `locals.session`/`locals.versionHistoryAdmin`).
 */
export async function list(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { resourceType, resourceId } = req.params
  if (!resourceType || !resourceId) {
    res.status(400).json({
      error: t('versionHistory.error.missingResource', undefined, {
        defaultValue: 'Resource type and ID are required',
      }),
      errorKey: 'versionHistory.error.missingResource',
    })
    return
  }

  if (!(await isVersionAuthorized(res, { resourceType, resourceId, userId }))) {
    res.status(404).json({
      error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
      errorKey: 'versionHistory.error.notFound',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 20))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const result = await getVersionsForResource(resourceType, resourceId, { limit, offset })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list versions', { resourceType, resourceId, error })
    res.status(500).json({
      error: t('versionHistory.error.listFailed', undefined, {
        defaultValue: 'Failed to list versions',
      }),
      errorKey: 'versionHistory.error.listFailed',
    })
  }
}

/**
 * Returns the total number of versions for a resource.
 *
 * Secure by default: returns 401 with no session, and 404 (no existence leak)
 * when the caller is not authorized for the parent resource.
 *
 * @param req - The request with `resourceType` and `resourceId` params.
 * @param res - The response object (reads `locals.session`/`locals.versionHistoryAdmin`).
 */
export async function versionCount(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { resourceType, resourceId } = req.params
  if (!resourceType || !resourceId) {
    res.status(400).json({
      error: t('versionHistory.error.missingResource', undefined, {
        defaultValue: 'Resource type and ID are required',
      }),
      errorKey: 'versionHistory.error.missingResource',
    })
    return
  }

  if (!(await isVersionAuthorized(res, { resourceType, resourceId, userId }))) {
    res.status(404).json({
      error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
      errorKey: 'versionHistory.error.notFound',
    })
    return
  }

  try {
    const total = await getVersionCount(resourceType, resourceId)
    res.json({ total })
  } catch (error) {
    logger.error('Failed to count versions', { resourceType, resourceId, error })
    res.status(500).json({
      error: t('versionHistory.error.countFailed', undefined, {
        defaultValue: 'Failed to count versions',
      }),
      errorKey: 'versionHistory.error.countFailed',
    })
  }
}

/**
 * Reads a single version of a resource by 1-based version number.
 *
 * Secure by default: returns 401 with no session, and 404 (no existence leak)
 * when the caller is not authorized for the parent resource.
 *
 * @param req - The request with `resourceType`, `resourceId`, and `version` params.
 * @param res - The response object (reads `locals.session`/`locals.versionHistoryAdmin`).
 */
export async function readByNumber(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { resourceType, resourceId, version } = req.params
  if (!resourceType || !resourceId) {
    res.status(400).json({
      error: t('versionHistory.error.missingResource', undefined, {
        defaultValue: 'Resource type and ID are required',
      }),
      errorKey: 'versionHistory.error.missingResource',
    })
    return
  }

  if (!(await isVersionAuthorized(res, { resourceType, resourceId, userId }))) {
    res.status(404).json({
      error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
      errorKey: 'versionHistory.error.notFound',
    })
    return
  }

  const versionNumber = parseInt(version ?? '', 10)
  if (!Number.isInteger(versionNumber) || versionNumber < 1) {
    res.status(400).json({
      error: t('versionHistory.error.invalidVersion', undefined, {
        defaultValue: 'Version number must be a positive integer',
      }),
      errorKey: 'versionHistory.error.invalidVersion',
    })
    return
  }

  try {
    const result = await getVersionByNumber(resourceType, resourceId, versionNumber)
    if (!result) {
      res.status(404).json({
        error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
        errorKey: 'versionHistory.error.notFound',
      })
      return
    }
    res.json(result)
  } catch (error) {
    logger.error('Failed to read version by number', {
      resourceType,
      resourceId,
      versionNumber,
      error,
    })
    res.status(500).json({
      error: t('versionHistory.error.readFailed', undefined, {
        defaultValue: 'Failed to read version',
      }),
      errorKey: 'versionHistory.error.readFailed',
    })
  }
}

/**
 * Reads a single version by ID.
 *
 * Secure by default: returns 401 with no session, and 404 (no existence leak)
 * when the version is missing OR the caller is not authorized for its parent
 * resource — a non-owner cannot tell the two apart, so another tenant's
 * snapshot is never disclosed. An opt-in {@link versionHistoryAdmin} may read
 * any version.
 *
 * @param req - The request with `versionId` param.
 * @param res - The response object (reads `locals.session`/`locals.versionHistoryAdmin`).
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { versionId } = req.params
  if (!versionId) {
    res.status(400).json({
      error: t('versionHistory.error.missingId', undefined, {
        defaultValue: 'Version ID is required',
      }),
      errorKey: 'versionHistory.error.missingId',
    })
    return
  }

  try {
    const version = await getVersionById(versionId)
    // Treat "not found" and "not authorized for the parent resource"
    // identically so the existence of another tenant's snapshot is not leaked.
    if (
      !version ||
      !(await isVersionAuthorized(res, {
        resourceType: version.resourceType,
        resourceId: version.resourceId,
        userId,
      }))
    ) {
      res.status(404).json({
        error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
        errorKey: 'versionHistory.error.notFound',
      })
      return
    }
    res.json(version)
  } catch (error) {
    logger.error('Failed to read version', { versionId, error })
    res.status(500).json({
      error: t('versionHistory.error.readFailed', undefined, {
        defaultValue: 'Failed to read version',
      }),
      errorKey: 'versionHistory.error.readFailed',
    })
  }
}

/**
 * Restores a prior version by appending a new version whose snapshot
 * matches it. Append-only — the existing rows are never mutated.
 *
 * Secure by default: returns 401 with no session, and 404 (no existence leak)
 * when the version is missing OR the caller is not authorized for its parent
 * resource — a non-owner can neither restore another tenant's version nor learn
 * that it exists. An opt-in {@link versionHistoryAdmin} may restore any version.
 *
 * @param req - The request with `versionId` param.
 * @param res - The response object (reads `locals.session`/`locals.versionHistoryAdmin`).
 */
export async function restore(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { versionId } = req.params
  if (!versionId) {
    res.status(400).json({
      error: t('versionHistory.error.missingId', undefined, {
        defaultValue: 'Version ID is required',
      }),
      errorKey: 'versionHistory.error.missingId',
    })
    return
  }

  const parsed = restoreVersionSchema.safeParse(req.body ?? {})
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'versionHistory.error.validationFailed' })
    return
  }

  // Verify the caller is authorized for the version's PARENT resource before
  // restoring. Treat "not found" and "not authorized" identically so a
  // non-owner can neither restore another tenant's version nor learn it exists.
  const target = await getVersionById(versionId)
  if (
    !target ||
    !(await isVersionAuthorized(res, {
      resourceType: target.resourceType,
      resourceId: target.resourceId,
      userId,
    }))
  ) {
    res.status(404).json({
      error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
      errorKey: 'versionHistory.error.notFound',
    })
    return
  }

  try {
    const restored = await restoreVersion(versionId, userId, parsed.data.reason ?? null)
    if (!restored) {
      res.status(404).json({
        error: t('versionHistory.error.notFound', undefined, { defaultValue: 'Version not found' }),
        errorKey: 'versionHistory.error.notFound',
      })
      return
    }
    res.status(201).json(restored)
  } catch (error) {
    logger.error('Failed to restore version', { versionId, userId, error })
    res.status(500).json({
      error: t('versionHistory.error.restoreFailed', undefined, {
        defaultValue: 'Failed to restore version',
      }),
      errorKey: 'versionHistory.error.restoreFailed',
    })
  }
}

/**
 * Returns the shallow diff between two versions of the same resource.
 *
 * Secure by default: returns 401 with no session, and 404 (no existence leak)
 * when either version is missing OR the caller is not authorized for the parent
 * resource the two versions share. An opt-in {@link versionHistoryAdmin} may
 * diff any versions.
 *
 * @param req - The request with `fromVersionId` and `toVersionId` params.
 * @param res - The response object (reads `locals.session`/`locals.versionHistoryAdmin`).
 */
export async function diff(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { fromVersionId, toVersionId } = req.params
  if (!fromVersionId || !toVersionId) {
    res.status(400).json({
      error: t('versionHistory.error.missingId', undefined, {
        defaultValue: 'Version ID is required',
      }),
      errorKey: 'versionHistory.error.missingId',
    })
    return
  }

  try {
    const result = await diffVersions(fromVersionId, toVersionId)
    // `diffVersions` already guarantees both versions share one resource; treat
    // "not found" and "not authorized for that parent resource" identically so
    // another tenant's snapshot/diff is never disclosed.
    if (
      !result ||
      !(await isVersionAuthorized(res, {
        resourceType: result.from.resourceType,
        resourceId: result.from.resourceId,
        userId,
      }))
    ) {
      res.status(404).json({
        error: t('versionHistory.error.diffNotFound', undefined, {
          defaultValue: 'One or both versions not found, or they belong to different resources',
        }),
        errorKey: 'versionHistory.error.diffNotFound',
      })
      return
    }
    res.json(result)
  } catch (error) {
    logger.error('Failed to diff versions', { fromVersionId, toVersionId, error })
    res.status(500).json({
      error: t('versionHistory.error.diffFailed', undefined, {
        defaultValue: 'Failed to diff versions',
      }),
      errorKey: 'versionHistory.error.diffFailed',
    })
  }
}

const router = Router()

router.post('/:resourceType/:resourceId/versions', create)
router.get('/:resourceType/:resourceId/versions', list)
router.get('/:resourceType/:resourceId/versions/count', versionCount)
router.get('/:resourceType/:resourceId/versions/:version', readByNumber)
router.get('/versions/:versionId', read)
router.post('/versions/:versionId/restore', restore)
router.get('/versions/:fromVersionId/diff/:toVersionId', diff)

export default router

