import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { logger } from '@molecule/api-logger'
import type { MoleculeRequest, MoleculeResponse } from '@molecule/api-resource'
import {
  acceptInvite as acceptInviteService,
  acceptInviteSchema,
  assertMember,
  createWorkspace,
  createWorkspaceSchema,
  deleteWorkspace,
  getWorkspace,
  inviteMember,
  inviteMemberSchema,
  listMembers,
  listPendingInvites,
  listWorkspacesForUser,
  removeMember,
  revokeInvite,
  updateMemberRole,
  updateMemberRoleSchema,
  updateWorkspace,
  updateWorkspaceSchema,
} from '@molecule/api-resource-workspace'

// Edit paths, request fields and JSON here. The services in @molecule/api-resource-workspace own storage.

/**
 * Creates a new workspace owned by the current user.
 *
 * @param req - The request with the workspace creation body (`name`, optional `slug`).
 * @param res - The response object.
 */
export async function create(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const parsed = createWorkspaceSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'workspace.error.validationFailed' })
    return
  }

  try {
    const workspace = await createWorkspace(userId, parsed.data)
    res.status(201).json(workspace)
  } catch (error) {
    logger.error('Failed to create workspace', { userId, error })
    res.status(500).json({
      error: t('workspace.error.createFailed', undefined, {
        defaultValue: 'Failed to create workspace',
      }),
      errorKey: 'workspace.error.createFailed',
    })
  }
}

/** Upper bound for the list page size — an uncapped `limit` is a table-dump primitive (e.g. `?limit=999999999`). */
const MAX_LIST_LIMIT = 500

/**
 * Lists workspaces the current user is a member of, paginated.
 *
 * @param req - The request with optional `limit`/`offset` query params.
 * @param res - The response object.
 */
export async function list(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const limit = Math.min(MAX_LIST_LIMIT, Math.max(1, parseInt(req.query.limit as string, 10) || 20))
  const offset = parseInt(req.query.offset as string, 10) || 0

  try {
    const result = await listWorkspacesForUser(userId, { limit, offset })
    res.json(result)
  } catch (error) {
    logger.error('Failed to list workspaces', { userId, error })
    res.status(500).json({
      error: t('workspace.error.listFailed', undefined, {
        defaultValue: 'Failed to list workspaces',
      }),
      errorKey: 'workspace.error.listFailed',
    })
  }
}

/**
 * Reads a single workspace by id. Caller must be a member.
 *
 * @param req - The request with `:id` param.
 * @param res - The response object.
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id } = req.params
  if (!id) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  try {
    await assertMember(id, userId)
    const workspace = await getWorkspace(id)
    if (!workspace) {
      res.status(404).json({
        error: t('workspace.error.notFound', undefined, { defaultValue: 'Workspace not found' }),
        errorKey: 'workspace.error.notFound',
      })
      return
    }
    res.json(workspace)
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Not a member of this workspace' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to read workspace', { userId, id, error })
    res.status(500).json({
      error: t('workspace.error.readFailed', undefined, {
        defaultValue: 'Failed to read workspace',
      }),
      errorKey: 'workspace.error.readFailed',
    })
  }
}

/**
 * Updates a workspace's mutable fields. Caller must be at least an admin.
 *
 * @param req - The request with `:id` param and patch body.
 * @param res - The response object.
 */
export async function update(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id } = req.params
  if (!id) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  const parsed = updateWorkspaceSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'workspace.error.validationFailed' })
    return
  }

  try {
    await assertMember(id, userId, 'admin')
    const workspace = await updateWorkspace(id, parsed.data)
    res.json(workspace)
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember' || code === 'workspace.error.insufficientRole') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Insufficient role for this workspace' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to update workspace', { userId, id, error })
    res.status(500).json({
      error: t('workspace.error.updateFailed', undefined, {
        defaultValue: 'Failed to update workspace',
      }),
      errorKey: 'workspace.error.updateFailed',
    })
  }
}

/**
 * Soft-deletes a workspace. Caller must be the owner.
 *
 * @param req - The request with `:id` param.
 * @param res - The response object.
 */
export async function del(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id } = req.params
  if (!id) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  try {
    await assertMember(id, userId, 'owner')
    await deleteWorkspace(id)
    res.status(204).end()
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember' || code === 'workspace.error.insufficientRole') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Only the owner can delete the workspace' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to delete workspace', { userId, id, error })
    res.status(500).json({
      error: t('workspace.error.deleteFailed', undefined, {
        defaultValue: 'Failed to delete workspace',
      }),
      errorKey: 'workspace.error.deleteFailed',
    })
  }
}

/**
 * Lists members of a workspace. Caller must be a member.
 *
 * @param req - The request with `:id` (workspace id) param.
 * @param res - The response object.
 */
export async function listAll(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id } = req.params
  if (!id) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  try {
    await assertMember(id, userId)
    const members = await listMembers(id)
    res.json({ data: members })
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Not a member of this workspace' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to list members', { userId, id, error })
    res.status(500).json({
      error: t('workspace.error.listMembersFailed', undefined, {
        defaultValue: 'Failed to list members',
      }),
      errorKey: 'workspace.error.listMembersFailed',
    })
  }
}

/**
 * Updates a member's role. Caller must be at least an admin.
 *
 * @param req - The request with `:id` (workspace) and `:userId` params and body `{ role }`.
 * @param res - The response object.
 */
export async function updateRole(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const callerId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!callerId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id, userId } = req.params
  if (!id || !userId) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  const parsed = updateMemberRoleSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'workspace.error.validationFailed' })
    return
  }

  try {
    const caller = await assertMember(id, callerId, 'admin')
    const member = await updateMemberRole(id, userId, parsed.data.role, caller.role)
    res.json(member)
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember' || code === 'workspace.error.insufficientRole') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Insufficient role for this workspace' }),
        errorKey: code,
      })
      return
    }
    if (code === 'workspace.error.cannotGrantHigherRole') {
      res.status(403).json({
        error: t(code, undefined, {
          defaultValue: 'Cannot assign a role higher than your own',
        }),
        errorKey: code,
      })
      return
    }
    if (code === 'workspace.error.lastOwner') {
      res.status(409).json({
        error: t(code, undefined, { defaultValue: 'Cannot demote the last owner' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to update member role', { callerId, id, userId, error })
    res.status(500).json({
      error: t('workspace.error.updateRoleFailed', undefined, {
        defaultValue: 'Failed to update member role',
      }),
      errorKey: 'workspace.error.updateRoleFailed',
    })
  }
}

/**
 * Removes a member from a workspace. Caller must be at least an admin
 * (or removing themself). Refuses to remove the last owner.
 *
 * @param req - The request with `:id` (workspace) and `:userId` params.
 * @param res - The response object.
 */
export async function remove(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const callerId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!callerId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id, userId } = req.params
  if (!id || !userId) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  try {
    if (callerId !== userId) {
      await assertMember(id, callerId, 'admin')
    } else {
      await assertMember(id, callerId)
    }
    await removeMember(id, userId)
    res.status(204).end()
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember' || code === 'workspace.error.insufficientRole') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Insufficient role for this workspace' }),
        errorKey: code,
      })
      return
    }
    if (code === 'workspace.error.lastOwner') {
      res.status(409).json({
        error: t(code, undefined, { defaultValue: 'Cannot remove the last owner' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to remove member', { callerId, id, userId, error })
    res.status(500).json({
      error: t('workspace.error.removeMemberFailed', undefined, {
        defaultValue: 'Failed to remove member',
      }),
      errorKey: 'workspace.error.removeMemberFailed',
    })
  }
}

/**
 * Creates a pending invite for a workspace. Caller must be at least an admin.
 *
 * @param req - The request with `:id` (workspace id) param and body `{ email, role? }`.
 * @param res - The response object.
 */
export async function invite(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id } = req.params
  if (!id) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  const parsed = inviteMemberSchema.safeParse(req.body)
  if (!parsed.success) {
    const errors = parsed.error.issues.map((e) => `${e.path.join('.')}: ${e.message}`).join(', ')
    res.status(400).json({ error: errors, errorKey: 'workspace.error.validationFailed' })
    return
  }

  try {
    const caller = await assertMember(id, userId, 'admin')
    const result = await inviteMember(id, parsed.data.email, caller.role, parsed.data.role)
    res.status(201).json(result)
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember' || code === 'workspace.error.insufficientRole') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Insufficient role to invite members' }),
        errorKey: code,
      })
      return
    }
    if (code === 'workspace.error.cannotGrantHigherRole') {
      res.status(403).json({
        error: t(code, undefined, {
          defaultValue: 'Cannot invite with a role higher than your own',
        }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to invite member', { userId, id, error })
    res.status(500).json({
      error: t('workspace.error.inviteFailed', undefined, {
        defaultValue: 'Failed to invite member',
      }),
      errorKey: 'workspace.error.inviteFailed',
    })
  }
}

/**
 * Lists pending invites for a workspace. Caller must be at least an admin.
 *
 * @param req - The request with `:id` (workspace id) param.
 * @param res - The response object.
 */
export async function listInvites(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id } = req.params
  if (!id) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  try {
    await assertMember(id, userId, 'admin')
    const invites = await listPendingInvites(id)
    res.json({ data: invites })
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember' || code === 'workspace.error.insufficientRole') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Insufficient role for this workspace' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to list invites', { userId, id, error })
    res.status(500).json({
      error: t('workspace.error.listInvitesFailed', undefined, {
        defaultValue: 'Failed to list invites',
      }),
      errorKey: 'workspace.error.listInvitesFailed',
    })
  }
}

/**
 * Accepts an invite using its single-use token. The current user joins
 * the invite's workspace with the invite's role.
 *
 * @param req - The request with body `{ token }`.
 * @param res - The response object.
 */
export async function accept(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const parsed = acceptInviteSchema.safeParse(req.body)
  if (!parsed.success) {
    res.status(400).json({
      error: t('workspace.error.invalidInvite', undefined, { defaultValue: 'Invalid invite' }),
      errorKey: 'workspace.error.invalidInvite',
    })
    return
  }

  try {
    const membership = await acceptInviteService(parsed.data.token, userId)
    res.status(200).json(membership)
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.invalidInvite') {
      res.status(400).json({
        error: t(code, undefined, { defaultValue: 'Invalid or expired invite' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to accept invite', { userId, error })
    res.status(500).json({
      error: t('workspace.error.acceptFailed', undefined, {
        defaultValue: 'Failed to accept invite',
      }),
      errorKey: 'workspace.error.acceptFailed',
    })
  }
}

/**
 * Revokes a pending invite. Caller must be at least an admin of the
 * workspace the invite belongs to.
 *
 * @param req - The request with `:id` (workspace) and `:inviteId` params.
 * @param res - The response object.
 */
export async function revoke(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const { id, inviteId } = req.params
  if (!id || !inviteId) {
    res.status(400).json({
      error: t('workspace.error.missingId', undefined, { defaultValue: 'Workspace id required' }),
      errorKey: 'workspace.error.missingId',
    })
    return
  }

  try {
    await assertMember(id, userId, 'admin')
    await revokeInvite(id, inviteId)
    res.status(204).end()
  } catch (error) {
    const code = (error as { code?: string }).code
    if (code === 'workspace.error.notAMember' || code === 'workspace.error.insufficientRole') {
      res.status(403).json({
        error: t(code, undefined, { defaultValue: 'Insufficient role for this workspace' }),
        errorKey: code,
      })
      return
    }
    logger.error('Failed to revoke invite', { userId, id, inviteId, error })
    res.status(500).json({
      error: t('workspace.error.revokeFailed', undefined, {
        defaultValue: 'Failed to revoke invite',
      }),
      errorKey: 'workspace.error.revokeFailed',
    })
  }
}

const router = Router()

router.post('/workspaces', create)
router.get('/workspaces', list)
router.post('/workspaces/invites/accept', accept)
router.get('/workspaces/:id', read)
router.patch('/workspaces/:id', update)
router.delete('/workspaces/:id', del)
router.get('/workspaces/:id/members', listAll)
router.patch('/workspaces/:id/members/:userId', updateRole)
router.delete('/workspaces/:id/members/:userId', remove)
router.post('/workspaces/:id/invites', invite)
router.get('/workspaces/:id/invites', listInvites)
router.delete('/workspaces/:id/invites/:inviteId', revoke)

export default router

