@molecule/api-streak.expressRouter:
import { Router } from 'express'

import { t } from '@molecule/api-i18n'
import { logger } from '@molecule/api-logger'
import type { MoleculeRequest, MoleculeResponse } from '@molecule/api-resource'
import { consumeFreeze, getStreak, recordActivity, resolveStreakConfig } from '@molecule/api-streak'

// Edit paths, request fields and JSON here. The services in @molecule/api-streak own storage.

/**
 * Records an activity event for the authenticated user under the
 * `:activityKind` route param.
 *
 * Server-authoritative by design: the request body is NOT read. The streak
 * config (reset window, freeze cap) is resolved on the SERVER
 * ({@link resolveStreakConfig}) and the event timestamp is the server clock —
 * so a client can only signal "I did this activity now", never the resulting
 * streak count/longest or the levers (`reset_after_hours`, `freezes_per_period`,
 * `when`) that would let it inflate its own streak.
 *
 * @param req - Express-compatible request.
 * @param res - Express-compatible response.
 */
export async function record(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const activityKind = req.params.activityKind
  if (!activityKind) {
    res.status(400).json({
      error: t('streak.error.missingActivityKind', undefined, {
        defaultValue: 'activity_kind is required',
      }),
      errorKey: 'streak.error.missingActivityKind',
    })
    return
  }

  try {
    const config = await resolveStreakConfig({ activityKind, userId })
    // Server clock — never a client-supplied `when`. A forged timestamp is the
    // primary streak-inflation vector (stage many "days" in one request burst).
    const result = await recordActivity(userId, config, new Date())
    res.status(200).json(result)
  } catch (error) {
    logger.error('Failed to record streak activity', { userId, activityKind, error })
    res.status(500).json({
      error: t('streak.error.recordFailed', undefined, {
        defaultValue: 'Failed to record streak activity',
      }),
      errorKey: 'streak.error.recordFailed',
    })
  }
}

/**
 * Reads the current streak state for the authenticated user under
 * the `:activityKind` route param.
 *
 * @param req - Express-compatible request.
 * @param res - Express-compatible response.
 */
export async function read(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const activityKind = req.params.activityKind
  if (!activityKind) {
    res.status(400).json({
      error: t('streak.error.missingActivityKind', undefined, {
        defaultValue: 'activity_kind is required',
      }),
      errorKey: 'streak.error.missingActivityKind',
    })
    return
  }

  try {
    const state = await getStreak(userId, activityKind)
    res.status(200).json(state)
  } catch (error) {
    logger.error('Failed to read streak', { userId, activityKind, error })
    res.status(500).json({
      error: t('streak.error.readFailed', undefined, {
        defaultValue: 'Failed to read streak',
      }),
      errorKey: 'streak.error.readFailed',
    })
  }
}

/**
 * Consumes one freeze for the authenticated user's streak, when the
 * server-resolved config allows. Returns the updated state and a
 * `freezeConsumed` flag.
 *
 * Server-authoritative: the freeze cap (`freezes_per_period`) is resolved on
 * the SERVER ({@link resolveStreakConfig}), never read from the request body —
 * a client cannot raise its own cap to burn unlimited freezes. With no resolver
 * registered the cap defaults to `0`, so this endpoint is a no-op until the app
 * explicitly grants freezes.
 *
 * @param req - Express-compatible request.
 * @param res - Express-compatible response.
 */
export async function freeze(req: MoleculeRequest, res: MoleculeResponse): Promise<void> {
  const userId = (res.locals.session as { userId?: string } | undefined)?.userId
  if (!userId) {
    res.status(401).json({
      error: t('resource.error.unauthorized', undefined, { defaultValue: 'Unauthorized.' }),
      errorKey: 'resource.error.unauthorized',
    })
    return
  }

  const activityKind = req.params.activityKind
  if (!activityKind) {
    res.status(400).json({
      error: t('streak.error.missingActivityKind', undefined, {
        defaultValue: 'activity_kind is required',
      }),
      errorKey: 'streak.error.missingActivityKind',
    })
    return
  }

  try {
    const config = await resolveStreakConfig({ activityKind, userId })
    const result = await consumeFreeze(userId, config)
    res.status(200).json(result)
  } catch (error) {
    logger.error('Failed to consume streak freeze', { userId, activityKind, error })
    res.status(500).json({
      error: t('streak.error.freezeFailed', undefined, {
        defaultValue: 'Failed to consume streak freeze',
      }),
      errorKey: 'streak.error.freezeFailed',
    })
  }
}

const router = Router()

router.post('/streaks/:activityKind', record)
router.get('/streaks/:activityKind', read)
router.post('/streaks/:activityKind/freeze', freeze)

export default router

