@molecule/api-two-factor.quickStart:
import { Router } from 'express'
import { generateSecret, getUrls, verify } from '@molecule/api-two-factor'
// `store` = YOUR server-side persistence: the datastore the environment provides (in
// molecule, `DATABASE_URL` via `@molecule/api-database` or a `pg` pool) — NOT an imported
// app's own hosted-DB admin client. Keyed by user id; the browser never touches it.
const router = Router()

router.get('/status', async (_req, res) => {
  const rec = await store.get(userId)
  res.json({ enabled: !!rec?.enabled }) // a boolean — never the secret
})

router.post('/setup', async (_req, res) => {
  const secret = generateSecret()
  await store.upsert(userId, { secret, enabled: false }) // pending, server-side only
  const { keyUrl, QRImageUrl } = await getUrls({ username, service: 'MyApp', secret })
  res.json({ keyUrl, QRImageUrl }) // the QR carries the secret — never return it raw
})

router.post('/enable', async (req, res) => {
  const rec = await store.get(userId)
  try {
    const { valid, timeStep, reason } = await verify({
      secret: rec.secret,
      token: req.body.token,
      afterTimeStep: rec.last_time_step,
    })
    if (!valid) {
      // reason === 'replay' means the code was ALREADY USED — tell the user to wait for
      // the next one; anything else is a wrong/expired code.
      return res.status(400).json({
        error: reason === 'replay' ? 'Code already used — wait for the next one' : 'Invalid code',
      })
    }
    await store.upsert(userId, { enabled: true, last_time_step: timeStep })
    res.json({ enabled: true })
  } catch (error) {
    // The STORED secret itself is unusable (corrupted record) — not a wrong code.
    // Tell the user to re-run setup rather than re-enter a code that can never verify.
    logger.error('2FA verify failed — stored secret unusable', { error, userId })
    res.status(500).json({ error: 'Two-factor setup is corrupted — please re-run setup' })
  }
})

@molecule/api-uploads.quickStart:
import { getProvider, getUploads, receiveUploads, sendUpload } from '@molecule/api-uploads'
// a bond called setProvider() at startup; the default, `@molecule/api-uploads-filesystem`, stores
// files under FILE_UPLOAD_PATH (./uploads), a folder that ignores itself in git: no .gitignore entry

router.post(
  '/files',
  requireAuth, // refuse anonymous requests before anything is stored
  receiveUploads({
    field: 'file',
    maxFileBytes: 5 * 1024 * 1024, // optional; 10 MiB when left out
    types: ['image/png', 'image/jpeg', 'application/pdf', 'text/plain'],
  }), // refuses: 415 not multipart or another type, 413 too large or too many, 400 no file or another field
  async (req, res) => {
    const [file] = getUploads(req, 'file') // fully stored; refusals never reach here
    await saveFileRow({ id: file.id, userId: getUserId(res), name: file.filename }) // own it
    res.status(201).json({ id: file.id }) // a throw or a 4xx/5xx answer removes the stored file
  },
)

router.get('/files/:id', async (req, res) => {
  const row = await getFileRow(req.params.id)
  if (!row || row.userId !== getUserId(res)) return res.status(404).end() // ownership → no IDOR
  const stream = await getProvider().getFile?.(row.id) // null for any id no stored file has, `../x` too
  if (!stream) return res.status(404).end()
  await sendUpload(res, stream, { filename: row.name }) // a download; { inline: true, type } shows an image
})

// Try it with the server running (curl builds the multipart body; add your auth header). A .txt
// file goes up as text/plain, which `types` allows:
//   echo hi > /tmp/a.txt
//   id=$(curl -fsS -F file=@/tmp/a.txt localhost:$PORT/files | node -pe 'JSON.parse(fs.readFileSync(0)).id')
//   curl -fsS localhost:$PORT/files/$id   → hi

