@molecule/app-angular.quickStart:
// main.ts — wire concrete providers into Angular DI:
import { Component, inject } from '@angular/core'
import { bootstrapApplication } from '@angular/platform-browser'
import {
  MoleculeAuthService,
  MoleculeThemeService,
  provideMolecule,
  t,
} from '@molecule/app-angular'
import { createJWTAuthClient } from '@molecule/app-auth'
import { provider as stateProvider } from '@molecule/app-state-zustand'
import { provider as themeProvider } from '@molecule/app-theme-css-variables'

const authClient = createJWTAuthClient({ baseURL: '/api' })

// dashboard.component.ts — inject the Molecule services:
@Component({
  selector: 'app-dashboard',
  template: `
    <div [style.background]="(theme$ | async)?.colors.background">
      <h1>{{ t('dashboard.welcome', {}, { defaultValue: 'Welcome!' }) }}</h1>
      <p>{{ (user$ | async)?.name }}</p>
      <button (click)="logout()">
        {{ t('auth.logout', {}, { defaultValue: 'Log out' }) }}
      </button>
    </div>
  `,
})
export class DashboardComponent {
  // Expose the reactive t() so template bindings re-evaluate on locale change.
  protected readonly t = t

  private authService = inject(MoleculeAuthService)
  private themeService = inject(MoleculeThemeService)

  user$ = this.authService.user$ // Observable<UserProfile | null>
  theme$ = this.themeService.theme$ // Observable<Theme>

  logout(): void {
    void this.authService.logout()
  }
}

// app.component.ts — the root that mounts the dashboard:
@Component({
  selector: 'app-root',
  imports: [DashboardComponent],
  template: '<app-dashboard />',
})
export class AppComponent {}

bootstrapApplication(AppComponent, {
  providers: [
    provideMolecule({
      state: stateProvider,
      auth: authClient,
      theme: themeProvider,
    }),
  ],
})

declarations.AuthClient:
interface AuthClient<T = UserProfile, TRegister extends RegisterExtraShape<TRegister> = Record<never, never>> {
  getState(): AuthState<T>;
  isAuthenticated(): boolean;
  getUser(): T | null;
  getSessionRevision?(): number;
  setUser(user: T | null): void;
  getAccessToken(): string | null;
  setAccessToken(token: string | null): void;
  setSession(session: AuthSessionSeed<T>): void;
  getRefreshToken(): string | null;
  login(credentials: LoginCredentials): Promise<AuthResult<T>>;
  logout(): Promise<void>;
  register(data: RegisterData<TRegister>): Promise<AuthResult<T>>;
  refresh(): Promise<AuthResult<T>>;
  requestPasswordReset(data: PasswordResetRequest): Promise<void>;
  confirmPasswordReset(data: PasswordResetConfirm): Promise<void>;
  updateProfile(data: Partial<T>): Promise<T>;
  changePassword(oldPassword: string, newPassword: string): Promise<void>;
  initialize(): Promise<void>;
  validateSession?(): Promise<void>;
  whenRestored?(): Promise<void>;
  subscribe(callback: (state: AuthState<T>) => void): () => void;
  onAuthChange(callback: (state: AuthState<T>) => void): () => void;
  getToken?(): string | null;
  addEventListener(listener: AuthEventListener<T>): () => void;
  destroy(): void;
}

declarations.AuthClientConfigOptions:
interface AuthClientConfigOptions<T extends object = UserProfile> {
  requestEnvelope?: string;
  baseURL?: string;
  loginEndpoint?: string;
  logoutEndpoint?: string | null;
  registerEndpoint?: string;
  refreshEndpoint?: string;
  profileEndpoint?: string | ((user: Readonly<T>) => string);
  profileUpdateMethod?: 'PATCH' | 'PUT' | 'POST';
  profileRequestBody?: (data: Partial<T>) => unknown;
  currentUserEndpoint?: string;
  currentUserRejectionStatuses?: readonly number[];
  cookieRestore?: 'hint' | 'always';
  requestTimeout?: number;
  storagePrefix?: string;
  tokenKey?: string;
  authScheme?: string;
  requestBody?: (kind: 'login' | 'register', payload: Record<string, unknown>) => unknown;
  mapRequestBody?: (payload: Record<string, unknown>, kind: 'login' | 'register') => unknown;
  mapAuthResponse?: (data: unknown) => AuthResult<NoInfer<T>> | AuthChallenge;
  storage?: 'memory' | StorageAdapter;
  shouldRestoreUser?: (user: T) => boolean;
  autoRefresh?: boolean;
  refreshBuffer?: number;
  forgotPasswordEndpoint?: string;
  resetPasswordEndpoint?: string;
  changePasswordEndpoint?: string | ((user: Readonly<T>) => string);
  changePasswordMethod?: 'POST' | 'PATCH';
  oauthProviders?: string[];
  oauthEndpoint?: string;
}

declarations.AuthResult:
interface AuthResult<T = UserProfile> {
  user: T;
  accessToken?: string;
  refreshToken?: string;
  expiresAt?: number;
  twoFactorRequired?: boolean;
}

declarations.AuthState:
